package com.bank.stats;

import java.util.*;
import java.util.logging.*;

public class AgeStatsDemo {
    private static final Logger log = Logger.getLogger("AgeStats");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> employees = List.of(
            new Employee("Rajesh", 35), new Employee("Priya", 30),
            new Employee("Amit", 28), new Employee("Vikram", 45));
        AgeStatsService service = new AgeStatsService();

        log.info(() -> "Total age: " + service.totalAge(employees));
        log.info(() -> "Average age: " + service.averageAge(employees).orElse(0));
        IntSummaryStatistics s = service.summary(employees);
        log.info(() -> "Min=" + s.getMin() + " Max=" + s.getMax()
                      + " Avg=" + s.getAverage() + " Count=" + s.getCount());
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final int age;
    Employee(String name, int age) { this.name = name; this.age = age; }
    int getAge() { return age; }
    String getName() { return name; }
}

// ─── Would be in service/AgeStatsService.java ───
class AgeStatsService {
    int totalAge(List<Employee> employees) {
        return employees.stream().mapToInt(Employee::getAge).sum(); // primitive sum
    }

    java.util.OptionalDouble averageAge(List<Employee> employees) {
        return employees.stream().mapToInt(Employee::getAge).average(); // empty → OptionalDouble.empty
    }

    IntSummaryStatistics summary(List<Employee> employees) {
        // ONE pass: count, sum, min, max, average
        return employees.stream().mapToInt(Employee::getAge).summaryStatistics();
    }
}
